<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class UnlockParticipation extends Model { public const INTERESTED='INTERESTED', COMMITTED='COMMITTED', UNLOCKED_PENDING_CONFIRMATION='UNLOCKED_PENDING_CONFIRMATION', CONFIRMED='CONFIRMED', FULFILLED='FULFILLED', CANCELLED_ON_TIME='CANCELLED_ON_TIME', NO_SHOW='NO_SHOW', EXPIRED='EXPIRED', REMOVED='REMOVED', WAITLISTED='WAITLISTED'; protected $guarded=[]; public function unlock(): BelongsTo { return $this->belongsTo(Unlock::class); } public static function terminal(string $status): bool { return in_array($status,[self::FULFILLED,self::CANCELLED_ON_TIME,self::EXPIRED,self::NO_SHOW,self::REMOVED],true); } protected function casts(): array { return ['interested_at'=>'datetime','committed_at'=>'datetime','confirmation_requested_at'=>'datetime','confirmed_at'=>'datetime','fulfilled_at'=>'datetime','expired_at'=>'datetime','no_show_at'=>'datetime','cancelled_at'=>'datetime']; } }
